(5779084, 840765, 105457, '<td valign="top">Good idea for the title, the octopus'' tentacles are resembling the speakers :)<br/>Nice macro, very good DOF, and good lighting.</td>', 'Good idea for the title, the octopus'' tentacles are resembling the speakers :)Nice macro, very good DOF, and good lighting.', '2009-12-23 09:50:17.000000', NULL, 1),
(5779085, 840886, 105457, '<td valign="top">Good choice for title, this cd case is very much like an UFO.<br/>Great DOF, and the colours add a lot to the composition.</td>', 'Good choice for title, this cd case is very much like an UFO.Great DOF, and the colours add a lot to the composition.', '2009-12-23 09:51:02.000000', NULL, 1),
(5779088, 840676, 105457, '<td valign="top">It does not appear to be an oyster...it looks a piece of ice melting. A wonderful shot, very contrasty and clear.</td>', 'It does not appear to be an oyster...it looks a piece of ice melting. A wonderful shot, very contrasty and clear.', '2009-12-23 09:53:42.000000', NULL, 1),
